def get_with_shield(self, key: str, now: float) -> bytes:
        entry = self.redis.get_entry(key)
        if entry and now < entry.soft_ttl:
            return entry.payload
        if entry and now < entry.hard_ttl:
            self._trigger_async_refresh(key)
            return entry.payload
        try:
            val, _ = self.sf.do(key, lambda: self._fetch_and_populate(key), wait_timeout=0.05)
            return val
        except TimeoutError:
            if entry:
                return entry.payload
            raise
